toolScript:
// State Management
        let isPointerLocked = false;
        let isCalibrating = false;
        let nominalDpi = 800;
        let activeReferenceDistanceMm = 85.60;
        let accumulatedDx = 0;
        let accumulatedDy = 0;
        const runsHistory = [];

        // DOM Element Cache
        const arena = document.getElementById('calibration-arena');
        const arenaStatusPill = document.getElementById('arena-status-pill');
        const arenaStatusDot = document.getElementById('arena-status-dot');
        const arenaStatusText = document.getElementById('arena-status-text');
        const arenaTitle = document.getElementById('arena-title');
        const arenaSubtitle = document.getElementById('arena-subtitle');
        const arenaIcon = document.getElementById('arena-icon');
        const liveDx = document.getElementById('live-dx');
        const liveDy = document.getElementById('live-dy');
        const liveTotal = document.getElementById('live-total');
        const resCpi = document.getElementById('res-cpi');
        const resDeviation = document.getElementById('res-deviation');
        const resDeviationLabel = document.getElementById('res-deviation-label');
        const resCounts = document.getElementById('res-counts');
        const resSpanLabel = document.getElementById('res-span-label');
        const resRating = document.getElementById('res-rating');
        const deviationBadge = document.getElementById('deviation-badge');
        const historyTableBody = document.getElementById('history-table-body');
        const aggregateBar = document.getElementById('aggregate-bar');
        const aggCount = document.getElementById('agg-count');
        const aggMean = document.getElementById('agg-mean');
        const aggDev = document.getElementById('agg-dev');
        const aggStd = document.getElementById('agg-std');
        const activeSpanDisplay = document.getElementById('active-span-display');

        // Web Audio Feedback Engine
        let audioCtx = null;
        function playChime(freq, type = 'sine', duration = 0.08) {
            try {
                if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
                if (audioCtx.state === 'suspended') audioCtx.resume();
                const osc = audioCtx.createOscillator();
                const gain = audioCtx.createGain();
                osc.type = type;
                osc.frequency.setValueAtTime(freq, audioCtx.currentTime);
                gain.gain.setValueAtTime(0.12, audioCtx.currentTime);
                gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + duration);
                osc.connect(gain);
                gain.connect(audioCtx.destination);
                osc.start();
                osc.stop(audioCtx.currentTime + duration);
            } catch (e) {}
        }

        // Tab Navigation
        function switchTab(tabId) {
            const tabs = ['cpi', 'snapping', 'compensator'];
            tabs.forEach(t => {
                const btn = document.getElementById(`tab-btn-${t}`);
                const content = document.getElementById(`tab-${t}-content`);
                if (t === tabId) {
                    btn.classList.add('active');
                    btn.classList.remove('text-slate-600', 'hover:bg-slate-100');
                    content.classList.remove('hidden');
                } else {
                    btn.classList.remove('active');
                    btn.classList.add('text-slate-600', 'hover:bg-slate-100');
                    content.classList.add('hidden');
                }
            });

            if (tabId === 'snapping') {
                initSnappingCanvas();
            } else if (tabId === 'compensator') {
                calculateCompensatedSens();
            }
        }

        // Configuration Handlers
        function setNominalDpi(val) {
            nominalDpi = Number(val);
            document.getElementById('nominal-dpi-input').value = val;
            updateCompensatorInputs();
        }

        document.getElementById('nominal-dpi-input').addEventListener('input', function() {
            const val = Number(this.value);
            if (val > 0) {
                nominalDpi = val;
                updateCompensatorInputs();
            }
        });

        function handleReferenceChange() {
            const sel = document.getElementById('reference-distance-select');
            const customContainer = document.getElementById('custom-distance-container');
            const customInput = document.getElementById('custom-distance-mm');

            if (sel.value === 'credit-card') {
                activeReferenceDistanceMm = 85.60;
                customContainer.classList.add('hidden');
            } else if (sel.value === '50mm') {
                activeReferenceDistanceMm = 50.00;
                customContainer.classList.add('hidden');
            } else if (sel.value === '100mm') {
                activeReferenceDistanceMm = 100.00;
                customContainer.classList.add('hidden');
            } else if (sel.value === '1inch') {
                activeReferenceDistanceMm = 25.40;
                customContainer.classList.add('hidden');
            } else if (sel.value === '2inches') {
                activeReferenceDistanceMm = 50.80;
                customContainer.classList.add('hidden');
            } else if (sel.value === 'custom') {
                customContainer.classList.remove('hidden');
                activeReferenceDistanceMm = Number(customInput.value) || 85.60;
            }

            const inches = activeReferenceDistanceMm / 25.4;
            activeSpanDisplay.innerText = `${activeReferenceDistanceMm.toFixed(2)} mm (${inches.toFixed(3)} in)`;
        }

        document.getElementById('custom-distance-mm').addEventListener('input', function() {
            const val = Number(this.value);
            if (val > 0) {
                activeReferenceDistanceMm = val;
                const inches = activeReferenceDistanceMm / 25.4;
                activeSpanDisplay.innerText = `${activeReferenceDistanceMm.toFixed(2)} mm (${inches.toFixed(3)} in)`;
            }
        });

        // Pointer Lock Lifecycle
        arena.addEventListener('click', function(e) {
            if (!isPointerLocked) {
                startCalibrationSession();
            } else {
                finishCalibrationRun();
            }
        });

        function startCalibrationSession() {
            arena.requestPointerLock = arena.requestPointerLock || arena.mozRequestPointerLock || arena.webkitRequestPointerLock;
            if (arena.requestPointerLock) {
                arena.requestPointerLock();
            } else {
                alert("Your browser does not support the PointerLock API. Please test in Chrome, Edge, Firefox, or Safari.");
            }
        }

        document.addEventListener('pointerlockchange', handlePointerLockChange);
        document.addEventListener('mozpointerlockchange', handlePointerLockChange);
        document.addEventListener('webkitpointerlockchange', handlePointerLockChange);

        function handlePointerLockChange() {
            const lockedElement = document.pointerLockElement || document.mozPointerLockElement || document.webkitPointerLockElement;
            if (lockedElement === arena) {
                isPointerLocked = true;
                isCalibrating = true;
                accumulatedDx = 0;
                accumulatedDy = 0;
                liveDx.innerText = '0';
                liveDy.innerText = '0';
                liveTotal.innerText = '0';

                arena.classList.add('arena-locked');
                arenaStatusPill.className = 'inline-flex items-center gap-2 px-3.5 py-1 rounded-full text-xs font-bold bg-sky-500/20 text-sky-300 border border-sky-400/30 shadow-sm animate-pulse';
                arenaStatusDot.className = 'w-2 h-2 rounded-full bg-sky-400';
                arenaStatusText.innerText = 'RECORDING SLIDE (Locked)';
                arenaTitle.innerText = 'Slide Mouse Across Reference Edge...';
                arenaTitle.className = 'text-xl sm:text-2xl font-black text-white tracking-tight';
                arenaSubtitle.innerText = 'Slide steadily across the card/ruler. Press SPACEBAR or Left-Click to finish.';
                arenaSubtitle.className = 'text-xs sm:text-sm text-slate-300 max-w-md mx-auto leading-relaxed';
                arenaIcon.className = 'w-16 h-16 mx-auto rounded-2xl bg-sky-500/20 text-sky-400 flex items-center justify-center shadow-inner';

                const asideStatus = document.getElementById('aside-engine-status');
                if (asideStatus) {
                    asideStatus.innerText = 'CALIBRATING';
                    asideStatus.className = 'text-sky-600 font-bold uppercase text-[10px] animate-pulse';
                }

                playChime(660, 'sine', 0.1);
            } else {
                if (isPointerLocked && isCalibrating) {
                    finishCalibrationRun();
                }
                isPointerLocked = false;
                arena.classList.remove('arena-locked');
                arenaStatusPill.className = 'inline-flex items-center gap-2 px-3.5 py-1 rounded-full text-xs font-bold bg-slate-100 text-slate-700 border border-slate-200 shadow-sm';
                arenaStatusDot.className = 'w-2 h-2 rounded-full bg-slate-400';
                arenaStatusText.innerText = 'Ready to Calibrate';
                arenaTitle.innerText = 'Click to Lock Mouse & Start Slide';
                arenaTitle.className = 'text-xl sm:text-2xl font-black text-slate-900 tracking-tight';
                arenaSubtitle.innerText = 'Align your mouse with your reference edge. Click to engage Pointer Lock, slide across, and press [SPACE] to finish.';
                arenaSubtitle.className = 'text-xs sm:text-sm text-slate-600 max-w-md mx-auto leading-relaxed';
                arenaIcon.className = 'w-16 h-16 mx-auto rounded-2xl bg-slate-100 text-slate-600 flex items-center justify-center shadow-inner';

                const asideStatus = document.getElementById('aside-engine-status');
                if (asideStatus) {
                    asideStatus.innerText = 'READY';
                    asideStatus.className = 'text-emerald-600 font-bold uppercase text-[10px]';
                }
            }
        }

        // Pointer Motion Accumulator
        document.addEventListener('mousemove', function(e) {
            if (!isPointerLocked || !isCalibrating) return;

            const movementX = e.movementX || e.mozMovementX || e.webkitMovementX || 0;
            const movementY = e.movementY || e.mozMovementY || e.webkitMovementY || 0;

            accumulatedDx += movementX;
            accumulatedDy += movementY;

            const axisMode = document.getElementById('axis-mode-select').value;
            let currentCounts = 0;
            if (axisMode === 'x-linear') {
                currentCounts = Math.abs(accumulatedDx);
            } else if (axisMode === 'y-linear') {
                currentCounts = Math.abs(accumulatedDy);
            } else {
                currentCounts = Math.round(Math.hypot(accumulatedDx, accumulatedDy));
            }

            liveDx.innerText = Math.abs(accumulatedDx).toLocaleString();
            liveDy.innerText = Math.abs(accumulatedDy).toLocaleString();
            liveTotal.innerText = currentCounts.toLocaleString();
        });

        // Spacebar Finish Listener
        document.addEventListener('keydown', function(e) {
            if ((e.code === 'Space' || e.key === ' ') && isPointerLocked) {
                e.preventDefault();
                document.exitPointerLock();
            }
        });

        // Complete Calibration & Compute Diagnostics
        function finishCalibrationRun() {
            isCalibrating = false;
            const axisMode = document.getElementById('axis-mode-select').value;
            let finalCounts = 0;
            if (axisMode === 'x-linear') {
                finalCounts = Math.abs(accumulatedDx);
            } else if (axisMode === 'y-linear') {
                finalCounts = Math.abs(accumulatedDy);
            } else {
                finalCounts = Math.round(Math.hypot(accumulatedDx, accumulatedDy));
            }

            if (finalCounts < 50) return;

            const inches = activeReferenceDistanceMm / 25.4;
            const calculatedCpi = finalCounts / inches;
            const deviation = ((calculatedCpi - nominalDpi) / nominalDpi) * 100;

            // Render Results
            resCpi.innerText = calculatedCpi.toFixed(1);
            resCounts.innerText = finalCounts.toLocaleString();
            resSpanLabel.innerText = `Over ${activeReferenceDistanceMm.toFixed(1)} mm`;

            const sign = deviation >= 0 ? '+' : '';
            resDeviation.innerText = `${sign}${deviation.toFixed(2)}%`;

            const absDev = Math.abs(deviation);
            let ratingText = '';
            let badgeBg = '';

            if (absDev <= 1.5) {
                ratingText = 'Esports Precision (±1.5%)';
                badgeBg = 'bg-emerald-100 text-emerald-800 border-emerald-300';
                resDeviation.className = 'text-2xl sm:text-3xl font-black text-emerald-600 mono-num';
                deviationBadge.className = `px-3 py-1 rounded-full text-xs font-bold border ${badgeBg} flex items-center gap-1.5`;
                deviationBadge.innerHTML = `<span class="w-1.5 h-1.5 rounded-full bg-emerald-500"></span> Excellent (${sign}${deviation.toFixed(2)}%)`;
                playChime(880, 'sine', 0.12);
            } else if (absDev <= 3.5) {
                ratingText = 'Commercial Variance (±3.5%)';
                badgeBg = 'bg-sky-100 text-sky-800 border-sky-300';
                resDeviation.className = 'text-2xl sm:text-3xl font-black text-sky-600 mono-num';
                deviationBadge.className = `px-3 py-1 rounded-full text-xs font-bold border ${badgeBg} flex items-center gap-1.5`;
                deviationBadge.innerHTML = `<span class="w-1.5 h-1.5 rounded-full bg-sky-500"></span> Normal (${sign}${deviation.toFixed(2)}%)`;
                playChime(740, 'sine', 0.12);
            } else if (absDev <= 6.0) {
                ratingText = 'Noticeable Drift (3.5%–6%)';
                badgeBg = 'bg-amber-100 text-amber-800 border-amber-300';
                resDeviation.className = 'text-2xl sm:text-3xl font-black text-amber-600 mono-num';
                deviationBadge.className = `px-3 py-1 rounded-full text-xs font-bold border ${badgeBg} flex items-center gap-1.5`;
                deviationBadge.innerHTML = `<span class="w-1.5 h-1.5 rounded-full bg-amber-500"></span> Noticeable (${sign}${deviation.toFixed(2)}%)`;
                playChime(550, 'triangle', 0.15);
            } else {
                ratingText = 'Severe Miscalibration (>6%)';
                badgeBg = 'bg-rose-100 text-rose-800 border-rose-300';
                resDeviation.className = 'text-2xl sm:text-3xl font-black text-rose-600 mono-num';
                deviationBadge.className = `px-3 py-1 rounded-full text-xs font-bold border ${badgeBg} flex items-center gap-1.5`;
                deviationBadge.innerHTML = `<span class="w-1.5 h-1.5 rounded-full bg-rose-500"></span> Heavy Drift (${sign}${deviation.toFixed(2)}%)`;
                playChime(440, 'sawtooth', 0.18);
            }

            resRating.innerText = ratingText;
            resDeviationLabel.innerText = deviation >= 0 ? 'Overshooting' : 'Undershooting';

            // Add to History
            runsHistory.push({
                run: runsHistory.length + 1,
                nominal: nominalDpi,
                distanceMm: activeReferenceDistanceMm,
                distanceIn: inches,
                counts: finalCounts,
                cpi: calculatedCpi,
                deviation: deviation
            });

            renderHistoryTable();
            updateCompensatorInputs(calculatedCpi);
        }

        function renderHistoryTable() {
            if (runsHistory.length === 0) {
                historyTableBody.innerHTML = `<tr><td colspan="5" class="px-3 py-4 text-center text-slate-400 italic font-sans text-xs">No runs recorded yet. Perform 3–5 slides across your credit card.</td></tr>`;
                aggregateBar.classList.add('hidden');
                return;
            }

            let html = '';
            let totalCpi = 0;
            let totalDev = 0;

            runsHistory.slice().reverse().forEach(r => {
                totalCpi += r.cpi;
                totalDev += r.deviation;
                const sign = r.deviation >= 0 ? '+' : '';
                const color = Math.abs(r.deviation) <= 1.5 ? 'text-emerald-600' : Math.abs(r.deviation) <= 4.0 ? 'text-sky-600' : 'text-amber-600';

                html += `<tr class="hover:bg-slate-50 transition-colors">
                    <td class="px-3 py-2 font-bold text-slate-800">#${r.run}</td>
                    <td class="px-3 py-2">${r.nominal} DPI</td>
                    <td class="px-3 py-2 font-bold text-slate-700">${r.counts.toLocaleString()}</td>
                    <td class="px-3 py-2 font-black text-slate-900">${r.cpi.toFixed(1)}</td>
                    <td class="px-3 py-2 font-black ${color}">${sign}${r.deviation.toFixed(2)}%</td>
                </tr>`;
            });

            historyTableBody.innerHTML = html;

            const meanCpi = totalCpi / runsHistory.length;
            const meanDev = totalDev / runsHistory.length;
            const variance = runsHistory.reduce((acc, curr) => acc + Math.pow(curr.cpi - meanCpi, 2), 0) / runsHistory.length;
            const stdDev = Math.sqrt(variance);

            aggCount.innerText = runsHistory.length;
            aggMean.innerText = meanCpi.toFixed(1) + ' CPI';
            const meanSign = meanDev >= 0 ? '+' : '';
            aggDev.innerText = `${meanSign}${meanDev.toFixed(2)}%`;
            aggStd.innerText = `±${stdDev.toFixed(2)} CPI`;
            aggregateBar.classList.remove('hidden');
        }

        function clearHistory() {
            runsHistory.length = 0;
            renderHistoryTable();
            resCpi.innerText = '---';
            resDeviation.innerText = '---%';
            resCounts.innerText = '0';
            resRating.innerText = 'Pending Run';
            deviationBadge.className = 'px-3 py-1 rounded-full text-xs font-bold bg-slate-100 text-slate-600 flex items-center gap-1.5';
            deviationBadge.innerHTML = '<span class="w-1.5 h-1.5 rounded-full bg-slate-400"></span> Awaiting Calibration';
        }

        function copyFullReport() {
            if (runsHistory.length === 0) {
                alert("Please perform at least one calibration run first.");
                return;
            }

            const meanCpi = runsHistory.reduce((acc, c) => acc + c.cpi, 0) / runsHistory.length;
            const meanDev = runsHistory.reduce((acc, c) => acc + c.deviation, 0) / runsHistory.length;
            const devSign = meanDev >= 0 ? '+' : '';
            const runsList = runsHistory.map(r => `  - Run #${r.run}: ${r.cpi.toFixed(1)} CPI (${r.deviation >= 0 ? '+' : ''}${r.deviation.toFixed(2)}% dev, ${r.counts} counts / ${r.distanceMm}mm)`).join('\n');

            const report = `=== ToolkitGen Mouse True DPI & CPI Diagnostic Report ===\n` +
                `Date: ${new Date().toLocaleString()}\n` +
                `Nominal Target DPI: ${nominalDpi} DPI\n` +
                `Runs Tested: ${runsHistory.length}\n` +
                `Aggregate Mean CPI: ${meanCpi.toFixed(1)} CPI\n` +
                `Sensor Deviation: ${devSign}${meanDev.toFixed(2)}%\n` +
                `Runs:\n${runsList}\n` +
                `Compensated CS2/Valorant Sens Factor: ${(nominalDpi / meanCpi).toFixed(4)}x\n` +
                `Benchmark URL: https://toolkitgen.com/tool/mouse_dpi_deviation_analyzer`;

            if (navigator.clipboard) {
                navigator.clipboard.writeText(report).then(() => {
                    alert("Diagnostic report copied to clipboard!");
                }).catch(() => prompt("Copy report:", report));
            } else {
                prompt("Copy report:", report);
            }
        }

        // Angle Snapping Canvas Engine
        let canvas, ctx;
        let isDrawing = false;
        let lastX = 0, lastY = 0;
        let angleSamples = [];

        function initSnappingCanvas() {
            canvas = document.getElementById('snapping-canvas');
            if (!canvas) return;
            ctx = canvas.getContext('2d');
            const rect = canvas.getBoundingClientRect();
            canvas.width = rect.width * window.devicePixelRatio;
            canvas.height = rect.height * window.devicePixelRatio;
            ctx.scale(window.devicePixelRatio, window.devicePixelRatio);
            drawGrid();

            canvas.addEventListener('mousedown', startDrawing);
            canvas.addEventListener('mousemove', drawTrace);
            window.addEventListener('mouseup', stopDrawing);
        }

        function drawGrid() {
            if (!ctx) return;
            const rect = canvas.getBoundingClientRect();
            ctx.clearRect(0, 0, rect.width, rect.height);
            ctx.strokeStyle = '#1e293b';
            ctx.lineWidth = 1;
            const step = 35;
            for (let x = 0; x < rect.width; x += step) {
                ctx.beginPath();
                ctx.moveTo(x, 0);
                ctx.lineTo(x, rect.height);
                ctx.stroke();
            }
            for (let y = 0; y < rect.height; y += step) {
                ctx.beginPath();
                ctx.moveTo(0, y);
                ctx.lineTo(rect.width, y);
                ctx.stroke();
            }
        }

        function startDrawing(e) {
            isDrawing = true;
            const rect = canvas.getBoundingClientRect();
            lastX = e.clientX - rect.left;
            lastY = e.clientY - rect.top;
        }

        function drawTrace(e) {
            if (!isDrawing) return;
            const rect = canvas.getBoundingClientRect();
            const currX = e.clientX - rect.left;
            const currY = e.clientY - rect.top;
            const dx = currX - lastX;
            const dy = currY - lastY;

            if (Math.hypot(dx, dy) >= 2) {
                ctx.strokeStyle = '#38bdf8';
                ctx.lineWidth = 2.5;
                ctx.lineCap = 'round';
                ctx.beginPath();
                ctx.moveTo(lastX, lastY);
                ctx.lineTo(currX, currY);
                ctx.stroke();

                const angle = Math.abs((Math.atan2(dy, dx) * 180) / Math.PI);
                angleSamples.push(angle);
                if (angleSamples.length > 300) angleSamples.shift();

                analyzeAngleSnapping();
                lastX = currX;
                lastY = currY;
            }
        }

        function stopDrawing() { isDrawing = false; }

        function clearCanvas() {
            angleSamples.length = 0;
            drawGrid();
            document.getElementById('canvas-snapping-status').innerText = 'Pure 1:1 Raw Trajectory (No Snapping)';
            document.getElementById('canvas-snapping-status').className = 'font-bold text-emerald-400 text-[11px]';
            document.getElementById('canvas-snapping-bias').innerText = '0.0%';
        }

        function analyzeAngleSnapping() {
            if (angleSamples.length < 30) return;
            let snappedCount = 0;
            angleSamples.forEach(a => {
                const mod90 = a % 90;
                const mod45 = a % 45;
                if (mod90 <= 1.5 || mod90 >= 88.5 || mod45 <= 1.5 || mod45 >= 43.5) snappedCount++;
            });

            const ratio = (snappedCount / angleSamples.length) * 100;
            const biasEl = document.getElementById('canvas-snapping-bias');
            const statusEl = document.getElementById('canvas-snapping-status');
            biasEl.innerText = `${ratio.toFixed(1)}%`;

            if (ratio > 45.0) {
                statusEl.innerText = 'Warning: Heavy Angle Snapping Detected!';
                statusEl.className = 'font-bold text-rose-400 text-[11px]';
            } else if (ratio > 28.0) {
                statusEl.innerText = 'Moderate Bias Detected';
                statusEl.className = 'font-bold text-amber-400 text-[11px]';
            } else {
                statusEl.innerText = 'Pure 1:1 Raw Trajectory (No Snapping)';
                statusEl.className = 'font-bold text-emerald-400 text-[11px]';
            }
        }

        // Sensitivity Compensator Engine
        const GAME_YAW_CONSTANTS = {
            cs2: 0.022,
            valorant: 0.07,
            apex: 0.022,
            overwatch: 0.0066,
            cod: 0.0066,
            r6: 0.00572,
            fortnite: 0.005555
        };

        function updateCompensatorInputs(newCpi) {
            if (newCpi && newCpi > 0) {
                document.getElementById('comp-measured-cpi').value = Math.round(newCpi);
            }
            calculateCompensatedSens();
        }

        function calculateCompensatedSens() {
            const game = document.getElementById('comp-game-select').value;
            const currentSens = Number(document.getElementById('comp-current-sens').value) || 1.0;
            const measuredCpi = Number(document.getElementById('comp-measured-cpi').value) || 800;

            const ratio = nominalDpi / measuredCpi;
            const compensatedSens = currentSens * ratio;

            document.getElementById('comp-result-sens').innerText = compensatedSens.toFixed(4);
            const intendedEdpi = nominalDpi * currentSens;
            document.getElementById('comp-intended-edpi').innerText = intendedEdpi.toFixed(1);

            const yaw = GAME_YAW_CONSTANTS[game] || 0.022;
            const countsFor360 = 360 / (currentSens * yaw);
            const cm360 = (countsFor360 / nominalDpi) * 2.54;
            document.getElementById('comp-cm-360').innerText = `${cm360.toFixed(2)} cm`;
        }

        function copyCompensatedSens() {
            const val = document.getElementById('comp-result-sens').innerText;
            if (navigator.clipboard) {
                navigator.clipboard.writeText(val).then(() => {
                    alert(`Compensated sensitivity (${val}) copied to clipboard!`);
                }).catch(() => prompt("Copy sensitivity:", val));
            } else {
                prompt("Copy sensitivity:", val);
            }
        }

        window.addEventListener('resize', function() {
            if (!document.getElementById('tab-snapping-content').classList.contains('hidden')) {
                initSnappingCanvas();
            }
        });
